"""Brain-dump -> TaskList. Two backends behind one interface:

- "openai": any OpenAI-compatible server (Ollama on the host box in prod, or Tinker's
  OpenAI-compatible endpoint with a tinker:// sampler path). Auto-traced by Sentry.
- "tinker": Tinker SamplingClient (used by eval for base models + tuned checkpoints).
"""
import json
import os
import re
import time
from dataclasses import dataclass
from functools import lru_cache

from pydantic import ValidationError

from app.prompts import MODEL_STOP, SYSTEM_PROMPT
from app.schema import TaskList

TINKER_OAI_URL = "https://tinker.thinkingmachines.dev/services/tinker-prod/oai/api/v1"


@dataclass
class ParseResult:
    tasks: TaskList | None
    raw: str
    latency_s: float
    valid_json: bool
    out_tokens: int | None = None


def extract_json(text: str) -> dict | None:
    text = re.sub(r"<think>.*?</think>", "", text, flags=re.S).strip()
    m = re.search(r"\{.*\}", text, flags=re.S)
    if not m:
        return None
    try:
        return json.loads(m.group(0))
    except json.JSONDecodeError:
        return None


def to_tasklist(text: str) -> TaskList | None:
    data = extract_json(text)
    if data is None:
        return None
    try:
        return TaskList.model_validate(data)
    except ValidationError:
        return None


def messages(note: str, shots: list[tuple[str, dict]] | None = None) -> list[dict]:
    msgs = [{"role": "system", "content": SYSTEM_PROMPT}]
    for dump, gold in shots or []:
        msgs += [{"role": "user", "content": dump}, {"role": "assistant", "content": json.dumps(gold)}]
    msgs.append({"role": "user", "content": note})
    return msgs


class OpenAIParser:
    def __init__(self, base_url: str, api_key: str, model: str, shots=None):
        from openai import OpenAI

        self.client = OpenAI(base_url=base_url, api_key=api_key)
        self.model, self.shots = model, shots

    def parse(self, note: str) -> ParseResult:
        t0 = time.perf_counter()
        resp = self.client.chat.completions.create(
            model=self.model, messages=messages(note, self.shots), temperature=0, max_tokens=900
        )
        raw = resp.choices[0].message.content or ""
        tl = to_tasklist(raw)
        usage = getattr(resp, "usage", None)
        return ParseResult(tl, raw, time.perf_counter() - t0, tl is not None,
                           getattr(usage, "completion_tokens", None))


class TinkerParser:
    def __init__(self, base_model: str, model_path: str | None = None, shots=None):
        import tinker

        sc = tinker.ServiceClient()
        self.client = sc.create_sampling_client(base_model=base_model, model_path=model_path)
        self.tok = self.client.get_tokenizer()
        self.shots = shots

    def parse(self, note: str) -> ParseResult:
        import tinker

        ids = render_prompt(self.tok, messages(note, self.shots))
        t0 = time.perf_counter()
        res = self.client.sample(
            prompt=tinker.types.ModelInput.from_ints(ids), num_samples=1,
            sampling_params=tinker.types.SamplingParams(max_tokens=900, temperature=0.0, stop=MODEL_STOP),
        ).result()
        toks = res.sequences[0].tokens
        raw = self.tok.decode(toks, skip_special_tokens=True)
        tl = to_tasklist(raw)
        return ParseResult(tl, raw, time.perf_counter() - t0, tl is not None, len(toks))


def render_prompt(tok, msgs: list[dict]) -> list[int]:
    """Chat-template the prompt with thinking disabled (Qwen3.x templates accept enable_thinking)."""
    try:
        text = tok.apply_chat_template(msgs, tokenize=False, add_generation_prompt=True, enable_thinking=False)
    except TypeError:
        text = tok.apply_chat_template(msgs, tokenize=False, add_generation_prompt=True)
    return tok.encode(text, add_special_tokens=False)


@lru_cache(maxsize=1)
def default_parser():
    backend = os.getenv("PARSER_BACKEND", "ollama")
    if backend == "ollama":
        return OpenAIParser(os.getenv("OLLAMA_BASE_URL", "http://localhost:11434/v1"), "ollama",
                            os.getenv("OLLAMA_MODEL", "actually"))
    if backend == "tinker-oai":
        return OpenAIParser(TINKER_OAI_URL, os.environ["TINKER_API_KEY"], os.environ["TINKER_SAMPLER_PATH"])
    return TinkerParser(os.getenv("BASE_MODEL", "Qwen/Qwen3.5-4B"), os.getenv("TINKER_SAMPLER_PATH"))

"""Fit forecast tasks into the free time he actually has."""
from app.schema import Forecast, Plan

DEADLINE_RANK = {"today": 0, "tomorrow": 1, "this_week": 2, None: 3}


def make_plan(forecasts: list[Forecast], deadlines: list, optional: list[bool], free_min: int) -> Plan:
    order = sorted(range(len(forecasts)),
                   key=lambda i: (optional[i], DEADLINE_RANK.get(deadlines[i], 3), forecasts[i].p50_min))
    do_now, move, used = [], [], 0.0
    for i in order:
        f = forecasts[i]
        if used + f.p50_min <= free_min:
            do_now.append(f)
            used += f.p50_min
        else:
            move.append(f)
    return Plan(
        free_min=free_min,
        guessed_total_min=sum(f.guess_min or 0 for f in forecasts),
        actual_total_min=round(sum(f.p50_min for f in forecasts), 1),
        do_now=do_now,
        move=move,
    )

import datetime as dt
import os
from functools import lru_cache
from pathlib import Path

import pandas as pd
from dotenv import load_dotenv
from fastapi import FastAPI, Header, HTTPException
from fastapi.responses import FileResponse
from pydantic import BaseModel

load_dotenv()

from app import db, observability  # noqa: E402
from app.forecast import MIN_ROWS, Forecaster, load_history, task_rows  # noqa: E402
from app.parser import default_parser  # noqa: E402
from app.plan import make_plan  # noqa: E402
from app.schema import Forecast  # noqa: E402

observability.init()
app = FastAPI(title="Actually")
ROOT = Path(__file__).resolve().parent.parent
PROFILES = {
    "demo": ROOT / "data/demo/tasks_demo.csv",  # synthetic, labelled as such in the UI
    "friend": ROOT / "data/private/tasks.csv",  # real; behind APP_PASSPHRASE
}


def check_profile(profile: str, passphrase: str | None):
    if profile not in PROFILES:
        raise HTTPException(404, "unknown profile")
    if profile != "demo" and passphrase != os.getenv("APP_PASSPHRASE"):
        raise HTTPException(401, "wrong passphrase")


@lru_cache(maxsize=4)
def forecaster(profile: str, n_logged: int) -> Forecaster:
    hist = load_history(str(PROFILES[profile]))
    extra = db.logged_rows(profile)
    if len(extra):
        hist = pd.concat([hist, extra[hist.columns.intersection(extra.columns)]], ignore_index=True)
    if len(hist) < MIN_ROWS:
        raise HTTPException(400, f"need at least {MIN_ROWS} past tasks, have {len(hist)}")
    return Forecaster(hist)


class DumpIn(BaseModel):
    text: str
    free_min: int = 180
    profile: str = "demo"


class LogIn(BaseModel):
    profile: str = "demo"
    task: str
    kind: str
    guess_min: int | None = None
    actual_min: int
    done_same_day: bool = True
    dreaded: bool = False
    left_house: bool = False


@app.post("/api/plan")
def plan(body: DumpIn, x_passphrase: str | None = Header(default=None)):
    check_profile(body.profile, x_passphrase)
    with observability.agent_span():
        parsed = default_parser().parse(body.text)
        if parsed.tasks is None or not parsed.tasks.tasks:
            raise HTTPException(422, "couldn't find tasks in that, try listing them with commas")
        tasks = parsed.tasks.tasks
        with observability.tool_span("tabpfn_forecast"):
            fc = forecaster(body.profile, len(db.logged_rows(body.profile)))
            rows = task_rows(tasks)
            pred = fc.predict(rows)
        forecasts = [
            Forecast(title=t.title, kind=t.kind, guess_min=t.guess_min,
                     p50_min=round(float(pred["p50"][i]), 1), p10_min=round(float(pred["p10"][i]), 1),
                     p90_min=round(float(pred["p90"][i]), 1),
                     p_done_today=None if pred["p_done"][i] is None else round(float(pred["p_done"][i]), 2),
                     why=fc.why(rows.iloc[i]))
            for i, t in enumerate(tasks)
        ]
        p = make_plan(forecasts, [t.deadline for t in tasks], [t.optional for t in tasks], body.free_min)
    return {"plan": p, "parse_latency_s": round(parsed.latency_s, 2), "history_rows": len(fc.history)}


@app.post("/api/log")
def log(body: LogIn, x_passphrase: str | None = Header(default=None)):
    check_profile(body.profile, x_passphrase)
    now = dt.datetime.now()
    db.log_task(body.profile, {
        "date": now.date().isoformat(), "task": body.task, "kind": body.kind, "guess_min": body.guess_min,
        "actual_min": body.actual_min, "done_same_day": int(body.done_same_day), "start_hour": now.hour,
        "dreaded": int(body.dreaded), "left_house": int(body.left_house), "has_deadline": 0,
    })
    return {"ok": True, "history_rows": len(load_history(str(PROFILES[body.profile]))) + len(db.logged_rows(body.profile))}


@app.get("/api/health")
def health():
    return {"ok": True, "parser_backend": os.getenv("PARSER_BACKEND", "ollama")}


@app.get("/")
def index():
    return FileResponse(ROOT / "app/static/index.html")

